/-- The product and products commute.
  This is `comp_pi_eq_pi_comp` generalised to all g, not just a single one. -/
theorem comp_pi_eq_pi_comp (γ₁ : ∀ i, Path.Homotopic.Quotient (bs i) (cs i)) :
    pi γ₀ ⬝ pi γ₁ = pi fun i ↦ γ₀ i ⬝ γ₁ i  := by
  induction γ₁ using Quotient.induction_on_pi with _ a;
  induction γ₀ using Quotient.induction_on_pi;
  simp only [pi_lift];
  rw [← Path.Homotopic.comp_lift, Path.trans_pi_eq_pi_trans, ← pi_lift];
  rfl

